		if root == "" {
			return fmt.Errorf("outside a repository; supply --repo")
		}
		return agentsetup.Install(root, render, opts.Stdout)
	}
	guide, err := render()
	if err != nil {
		return err
	}
	_, err = fmt.Fprint(opts.Stdout, guide)
	return err
}
