	guideInlineRE    = regexp.MustCompile("`([^`]+)`")
	guideHeadingRE   = regexp.MustCompile(`^### .*?([a-z][a-z0-9-]*) —`)
	guideSectionRE   = regexp.MustCompile(`^#{1,3}\s`)
