				t.Fatal(err)
			}
			path := filepath.Join(dir, "manifest.json")
			prefix := `{"schema_version":3,"sessions":[{"summary":{"intent":"`
			suffix := `"}}]}`
			f, err := os.Create(path)
			if err != nil {
				t.Fatal(err)
			}
			if _, err := f.WriteString(prefix + strings.Repeat("x", size-len(prefix)-len(suffix)) + suffix); err != nil {
