				t.Fatal(err)
			}
			before, err := os.ReadFile(filepath.Join(dir, exportManifestFileName))
			if err != nil {
				t.Fatal(err)
			}
			got.GeneratedAt = time.Date(10000, 1, 1, 0, 0, 0, 0, time.UTC)
